import{_ as s,C as r,o as n,c as d,j as e,a,E as i,ag as c}from"./chunks/framework.HG0H2VLS.js";const w=JSON.parse('{"title":"CrmAnalysis","description":"","frontmatter":{},"headers":[],"relativePath":"cc-templates/crm-analysis.md","filePath":"cc-templates/crm-analysis.md"}'),l={name:"cc-templates/crm-analysis.md"};function h(u,t,g,p,m,b){const o=r("ComponentDemo");return n(),d("div",null,[t[0]||(t[0]=e("hr",null,null,-1)),t[1]||(t[1]=e("h2",{id:"title-crmanalysis",tabindex:"-1"},[a("title: CrmAnalysis "),e("a",{class:"header-anchor",href:"#title-crmanalysis","aria-label":'Permalink to "title: CrmAnalysis"'},"​")],-1)),t[2]||(t[2]=e("h1",{id:"crmanalysis",tabindex:"-1"},[a("CrmAnalysis "),e("a",{class:"header-anchor",href:"#crmanalysis","aria-label":'Permalink to "CrmAnalysis"'},"​")],-1)),t[3]||(t[3]=e("blockquote",null,[e("p",null,[e("code",null,"/control/crm-analysis"),a(" on v3 on the Flowbite benchmark, built on the Live Dashboard (links its CSS): 'Your CRM at a glance' (classic's Contacts → Accounts and Opportunities → Wins pairs, each arrow carrying its relation: per account, % won), Contracts and Opportunities cards (classic's figures, This month as a calendar heatmap and 12 months as a gradient area chart, switched by a SegmentedControl; subgrid-aligned), Top customers and Open pipeline by stage (classic's open rule shown), Contact notes and Unsubscribes activity cards (30-day total, change vs previous 30, gradient area sparkline); the Wins chip is a radial win-rate gauge; one colour scheme, lagoon")])],-1)),i(o,{src:"/demos/src/cc/templates/CrmAnalysis/CrmAnalysis.html"}),t[4]||(t[4]=c('<h2 id="classic-→-v3" tabindex="-1">Classic → v3 <a class="header-anchor" href="#classic-→-v3" aria-label="Permalink to &quot;Classic → v3&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic</th><th>v3</th></tr></thead><tbody><tr><td>Top row: CONTACTS → ACCOUNTS, OPPORTUNITIES → WINS (two pairs, an arrow image each)</td><td><strong>Your CRM at a glance</strong>: the same two pairs, each stat a soft icon chip + label + value, linking to its listing. Each arrow now carries the relation it stands for, in a Badge on an arrowed hairline: <strong>&quot;3.6 per account&quot;</strong>, <strong>&quot;33% won&quot;</strong> (wins ÷ all opportunities, as both of classic&#39;s counts are all-time). The win rate is also <strong>drawn</strong>: the Wins chip is a radial gauge filled to it, sweeping up on load. &quot;All time, as of …&quot; in the card head</td></tr><tr><td>CONTRACTS THIS MONTH (line, by day) + CONTRACTS (Last 12 Months) (line, by month)</td><td><strong>Contracts</strong> card: one chart with a <strong>This month / 12 months</strong> SegmentedControl and a count Badge (&quot;6 this month&quot;). <strong>This month is a calendar heatmap</strong>: a Mon–Sun table, each day shaded by its count, days to come outlined, today ringed, with a None → Most key. Daily counts here are small and patchy, so a line or bars were mostly empty space; the calendar shows busy days, gaps and the weekly rhythm at a glance. <strong>12 months is a gradient area chart</strong> (Live Dashboard&#39;s treatment, monotone smoothing so it never dips below zero), with a crosshair tooltip and <strong>View as table</strong> (Mark, 2026-10-05: &quot;more visually striking&quot; than the first pass&#39;s bars)</td></tr><tr><td>TOTAL CONTRACT VALUE / CUSTOMERS / AVE. CONTRACT VALUE strip</td><td>The card&#39;s figures, the first leading at StatCard Xl&#39;s value size. &quot;Ave. contract value&quot; is labelled <strong>Ave. value per customer</strong>, as Contract Analysis already corrected (it is total ÷ customers)</td></tr><tr><td>—</td><td><strong>Top customers</strong> (new): the five biggest accounts by contract value with share bars, linking to Contract Analysis › Top accounts</td></tr><tr><td>OPPORTUNITIES THIS MONTH + Opportunities (Last 12 Months)</td><td><strong>Opportunities</strong> card, same shape. Classic&#39;s rules are kept: &quot;this month&quot; leaves out Closed Won and Closed (Stage NOT IN 9, 10), so the subtitle says &quot;still in play&quot;; the 12 months count every opportunity</td></tr><tr><td>OPEN OPPORTUNITY VALUE / OPEN OPPORTUNITIES / AVE. OPPORTUNITY VALUE strip</td><td>The card&#39;s figures</td></tr><tr><td>—</td><td><strong>Open pipeline by stage</strong> (new): the five open stages in stage order with count, value and a share bar, each linking to the opportunities listing filtered to that stage; then classic&#39;s open rule said aloud: &quot;Not counted as open, as in classic: 18 prospecting and 95 on hold, plus everything closed&quot;</td></tr><tr><td>Contact Notes (Last 30 days) (line)</td><td><strong>Contact notes</strong> activity card: the 30-day total, a Badge with the change against the 30 days before, a <strong>gradient area sparkline</strong> (the Flowbite KPI card&#39;s chart; first and last dates only), the busiest day and the daily average, and a table view</td></tr><tr><td>Unsubscribes (Last 30 days) (line)</td><td><strong>Unsubscribes</strong> card, same shape. A rise is bad news here, so an increase reads <strong>danger</strong> and a fall success; within ±2% is neutral on both cards</td></tr><tr><td>A chart section disappears when it has no data</td><td>The card stays, with &quot;No contracts created this month yet.&quot; in place of the chart</td></tr></tbody></table><h2 id="data-rules-worth-a-look" tabindex="-1">Data rules (worth a look) <a class="header-anchor" href="#data-rules-worth-a-look" aria-label="Permalink to &quot;Data rules (worth a look)&quot;">​</a></h2><ul><li><strong>Contracts are Contract Analysis&#39;s own data and rule.</strong> The page loads <code>../ContractAnalysis/contract-analysis-data.js</code> and counts contracts that are not cancelled and not archived, so the two screens show the same value, customers and average (checked: £5,909,300, 45, £131,318, and 6 this month). Classic CRM Analysis filtered on CancelledYN only; Contract Analysis&#39;s notes set the shared rule.</li><li><strong>&quot;Open&quot; opportunities</strong> are Stage NOT IN (1, 9, 10, 11): Prospecting is not open in classic. The stage names are AffinoComrz&#39;s real CRMProfileOpportunityStage rows: Prospecting, Qualification, Needs Analysis, Value Proposition, Proposal / Price / Quote, Negotiation / Review, Closed Won, Closed, On Hold.</li><li><strong>&quot;Contact notes&quot; counts every note.</strong> Classic&#39;s query has no note-type or contact filter, despite the title. Kept as classic; flagged for Lynx.</li><li><strong>The comparisons are new data:</strong> the 30 days before (for the notes / unsubscribes change) and opportunities by stage (for the pipeline). Both come from the same tables as classic&#39;s own queries.</li><li>The demo uses Contract Analysis&#39;s fixed &quot;today&quot; (26 Sep 2026), so &quot;this month&quot; is most of a month.</li></ul><h2 id="layout-values-all-borrowed-no-new-tokens" tabindex="-1">Layout values (all borrowed, no new tokens) <a class="header-anchor" href="#layout-values-all-borrowed-no-new-tokens" aria-label="Permalink to &quot;Layout values (all borrowed, no new tokens)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Token</th><th>From</th></tr></thead><tbody><tr><td>Page grid</td><td>2 columns, <code>spacing-5</code> gap (<code>spacing-4</code> full width); glance card spans both</td><td>the other dashboards&#39; gap</td></tr><tr><td>Pipeline cards</td><td>a <strong>subgrid</strong> of the page&#39;s rows (head, figures, chart, ranked list) with <code>row-gap: spacing-5</code>, so both cards&#39; sections start on one line however their labels wrap; <code>minmax(0, 1fr)</code> column</td><td>— measured: the implicit min-content column overflowed at 390 (324 / 309)</td></tr><tr><td>Card chrome, title, ranked rows, table view</td><td>as Live Dashboard</td><td>Live Dashboard</td></tr><tr><td>Share bars</td><td>Live Dashboard&#39;s bar, filled <code>accent-lagoon-solid</code> (the charts&#39; token, not <code>surface-brand</code>, so a client brand change cannot split bars from charts)</td><td>Mark, 2026-10-05</td></tr><tr><td>Glance stat icon chip</td><td><code>spacing-8</code>, <code>radius-md</code>, 16px icon, <code>accent-lagoon-soft</code> / <code>-soft-fg</code></td><td>StatCard&#39;s soft icon</td></tr><tr><td>Stat / figure labels</td><td>body, <code>fixed-xxs</code>, semibold, uppercase, <code>text-contrast</code></td><td>StatCard&#39;s breakdown label</td></tr><tr><td>Stat value, lead figure</td><td>title, bold, <code>fixed-xl</code>, <code>leading-lg</code></td><td>StatCard Xl&#39;s value</td></tr><tr><td>Other figures</td><td><code>fixed-sm</code>, bold, <code>leading-lg</code> (the lead&#39;s line box, so the three share a baseline)</td><td>—</td></tr><tr><td>Relation hairline + arrowhead</td><td>1px <code>border-primary</code>; arrowhead <code>spacing-3</code> square, rotated</td><td>—</td></tr><tr><td>12-month area chart height</td><td><code>size-3</code> (192px)</td><td>half a hero, as two sit side by side</td></tr><tr><td>Calendar cell</td><td><code>spacing-7</code> tall, <code>radius-sm</code>, <code>spacing-1</code> spacing; day number title <code>fixed-3xs</code> medium</td><td>—</td></tr><tr><td>Calendar shades</td><td>none: <code>text-contrast</code> 12% into <code>surface-primary</code>; then <code>accent-lagoon-solid</code> 35% / 65% into <code>surface-primary</code>, then solid (number in dark ink, see Colour); to come: 1px <code>border-secondary</code> inset; today: 2px <code>text-primary</code> inset</td><td><code>color-mix()</code> of tokens, no new tokens</td></tr><tr><td>Win-rate gauge</td><td>the chip (<code>spacing-8</code>) as a <code>conic-gradient</code> ring: <code>accent-lagoon-solid</code> to the rate on <code>accent-lagoon-soft</code>, a <code>spacing-1</code> ring around a <code>surface-primary</code> hole; sweeps 900ms via a registered <code>--cc-crm-pct</code></td><td>StatCard&#39;s soft icon chip</td></tr><tr><td>Activity value</td><td><code>fixed-3xl</code>, bold, <code>leading-xl</code></td><td>— the Flowbite KPI-with-chart scale</td></tr><tr><td>Sparkline height</td><td><code>size-1</code> (128px)</td><td>—</td></tr><tr><td>Meta / note / &quot;more&quot; link text</td><td>title, <code>fixed-3xs</code>, medium, <code>text-contrast</code> (link <code>text-secondary</code>)</td><td>Sales Leaderboard&#39;s meta text (Mark, 2026-10-05)</td></tr><tr><td>Area charts</td><td>2px line, fill fading 25% → 0, monotone, crosshair on hover</td><td>Live Dashboard</td></tr></tbody></table><h2 id="colour" tabindex="-1">Colour <a class="header-anchor" href="#colour" aria-label="Permalink to &quot;Colour&quot;">​</a></h2><p><strong>One colour scheme, lagoon</strong> (Mark, 2026-10-05): every data mark — area charts, calendar shades, share bars, the win-rate gauge — is <code>accent-lagoon-solid</code>, and the icon chips are lagoon soft (each icon is named by its label). Every chart is single-series, so no pairing needs CVD validation. The calendar is a <strong>sequential</strong> scale of that one hue (dataviz rule), checked for one direction in each theme by computed OKLab lightness, none → most: light 0.95 / 0.86 / 0.76 / 0.65, dark 0.34 / 0.41 / 0.52 / 0.65. &quot;None&quot; is a 12% neutral mix: <code>surface-secondary</code> on the dark card is LIGHTER than the first shade, so the scale ran backwards there. Day numbers on solid lagoon are dark ink in both themes: its white <code>-fg</code> is 3.15:1, so light mode uses <code>text-primary</code> (5.17:1) and dark mode <code>surface-primary</code> (4.65:1), as dark mode&#39;s <code>text-primary</code> is light. The status colours on the delta Badges stay as they are (reserved for good / bad, with an icon). Text stays in text tokens.</p><h2 id="responsive" tabindex="-1">Responsive <a class="header-anchor" href="#responsive" aria-label="Permalink to &quot;Responsive&quot;">​</a></h2><ul><li><strong>Below 1023 (<code>cs-page</code>):</strong> the two glance pairs stack, each keeping its stat — relation — stat line.</li><li><strong>Below 767:</strong> one column; card heads wrap (title, then the period switch).</li><li><strong>Pipeline figures</strong> fold to the lead figure over the other two whenever the figures&#39; box is under 420px (it is ~456 at a 1440 window, ~350 at 1200) (a size container on <code>.cc-crm__figures-wrap</code>), so a one-word label like &quot;OPPORTUNITIES&quot; never runs into its neighbour. The container is the wrapper, not the card: a size container gets layout containment, which switched the card&#39;s subgrid off (the two heads went 10px out of line).</li><li><strong>Below 480:</strong> a pair stacks its stats with the relation Badge between them.</li><li>Measured at 390: page 323 / 323, no card overflowing. At 1200 the two cards&#39; titles both sit at 415 and their lists at 929.</li></ul><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><p>The glance card&#39;s arrows are decorative; a visually-hidden sentence says the same (&quot;3,842 contacts across 1,064 accounts, 3.6 per account. 1,296 opportunities, of which 423 won, 33%.&quot;). Each pair is a labelled group. The period switch is SegmentedControl&#39;s radio group (roving tabindex). The calendar is a real <code>&lt;table&gt;</code> (caption, weekday <code>&lt;th&gt;</code> with full names in <code>&lt;abbr&gt;</code>, each day&#39;s count as visually-hidden text and a <code>title</code>), so it is its own table view and the separate one is hidden in that mode. Every canvas is <code>role=&quot;img&quot;</code> with a label giving the period and total, and has a table view. The gauge sweep is off under reduced motion. Delta Badges carry an icon and a sign, not colour alone.</p><h2 id="backend-todo-backend-crmanalysis" tabindex="-1">Backend (<code>TODO(backend:CrmAnalysis)</code>) <a class="header-anchor" href="#backend-todo-backend-crmanalysis" aria-label="Permalink to &quot;Backend (`TODO(backend:CrmAnalysis)`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>id</th><th>What</th></tr></thead><tbody><tr><td><code>crm-data</code></td><td>Every figure is mock. Live = classic&#39;s own queries in CRMAnalysis.cfm (listed in <code>crm-analysis-data.js</code>), contracts under Contract Analysis&#39;s shared &quot;counted&quot; rule, plus two small additions: the previous 30 days for notes / unsubscribes, and open opportunities grouped by stage</td></tr></tbody></table>',14))])}const f=s(l,[["render",h]]);export{w as __pageData,f as default};
